#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    std::vector<int> peopleIndexes(std::vector<std::vector<std::string>>& favoriteCompanies) {
        int n = favoriteCompanies.size();
        std::vector<std::unordered_set<std::string>> sets(n);
        for (int i = 0; i < n; ++i) {
            for (const auto& c : favoriteCompanies[i]) sets[i].insert(c);
        }
        std::vector<int> res;
        for (int i = 0; i < n; ++i) {
            bool isSub = false;
            for (int j = 0; j < n; ++j) {
                if (i != j && sets[j].size() > sets[i].size()) {
                    bool allIn = true;
                    for (const auto& comp : sets[i]) {
                        if (!sets[j].count(comp)) {
                            allIn = false;
                            break;
                        }
                    }
                    if (allIn) {
                        isSub = true;
                        break;
                    }
                }
            }
            if (!isSub) res.push_back(i);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies) {
        int n = favoriteCompanies.size();
        List<Set<String>> sets = new ArrayList<>(n);
        for (List<String> fc : favoriteCompanies) sets.add(new HashSet<>(fc));
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean isSub = false;
            Set<String> s1 = sets.get(i);
            for (int j = 0; j < n; j++) {
                if (i != j && sets.get(j).size() > s1.size()) {
                    if (sets.get(j).containsAll(s1)) {
                        isSub = true;
                        break;
                    }
                }
            }
            if (!isSub) res.add(i);
        }
        return res;
    }
}

var peopleIndexes = function(favoriteCompanies) {
