    const res = [];
    for (let i = 0; i < sets.length; i++) {
        let isSub = false;
        const s1 = sets[i];
        for (let j = 0; j < sets.length; j++) {
            if (i !== j && sets[j].size > s1.size) {
                let allIn = true;
                for (const comp of s1) {
                    if (!sets[j].has(comp)) {
                        allIn = false;
                        break;
                    }
                }
                if (allIn) {
